#!/usr/bin/env bash
# run_rx_eq_div_stress_xsim.sh — ROBUST full-|H|-range ZF divider stress gate
#
# UUT : rtl/rx_eq_complex_div.v  (+ rtl/rx_equalizer_recip_lut.hex)
# TB  : tb/rx_eq_div_stress_tb.sv
# Vectors : generated by scripts/gen_rx_eq_div_stress.py (49 cases spanning
#           |H|^2 over the full dynamic range incl. deep nulls + guard + sat)
#
# GATE OUTPUT (exactly one): GATE_RX_EQ_DIV_STRESS: PASS|FAIL
# EXIT 0 iff PASS.
set -uo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
cd "${ROOT}"

XSIM_BIN="${XSIM_BIN:-/opt/Xilinx/Vivado/2021.1/bin}"
WORK="${ROOT}/sim_out/rx_eq_div_stress"

# (re)generate stress vectors
python3 "${ROOT}/scripts/gen_rx_eq_div_stress.py" > "${WORK%/*}/.stressgen.log" 2>&1 || {
    echo "GATE_RX_EQ_DIV_STRESS: FAIL (vector gen)"; tail -20 "${WORK%/*}/.stressgen.log"; exit 1; }

mkdir -p "${WORK}/golden_lut"
cp "${ROOT}/rtl/rx_equalizer_recip_lut.hex" "${WORK}/golden_lut/"

cd "${WORK}"
export PATH="${XSIM_BIN}:${PATH}"

xvlog -sv "${ROOT}/rtl/rx_eq_complex_div.v" \
          "${ROOT}/tb/rx_eq_div_stress_tb.sv" \
      > xvlog_stress.log 2>&1 || { echo "GATE_RX_EQ_DIV_STRESS: FAIL (xvlog)"; tail -30 xvlog_stress.log; exit 1; }

xelab -debug off rx_eq_div_stress_tb -s eq_stress \
      > xelab_stress.log 2>&1 || { echo "GATE_RX_EQ_DIV_STRESS: FAIL (xelab)"; tail -30 xelab_stress.log; exit 1; }

xsim eq_stress -R > xsim_stress.log 2>&1
grep -E "GATE_RX_EQ_DIV_STRESS|worst|cases=|MISMATCH|GUARD" xsim_stress.log

grep -q "GATE_RX_EQ_DIV_STRESS: PASS" xsim_stress.log && exit 0 || exit 1
